clear;
clc;
close all;

%% Step 1: Create dataset (hourly data for 4 weeks)

hours = 24 * 28; % 4 weeks
t = (1:hours)';

% Simulated energy usage (kWh)
% Base usage + daily pattern + randomness
baseLoad = 1.5;
dailyPattern = 2 * sin(2*pi*(t/24 - 0.25)) + 2;
noise = 0.5 * randn(size(t));

energy = baseLoad + dailyPattern + noise;

% Remove negatives
energy(energy < 0) = 0;

%% Step 2: Clean data and compute weekly totals

% Weekly totals (7 days = 168 hours)
weeklyTotals = reshape(energy(1:168*4), 168, 4);
weeklyTotals = sum(weeklyTotals);

% Peak usage hour
[maxUsage, peakIndex] = max(energy);

%% Step 3: Plots

% (i) Time-series plot
figure; %[output:78cbdbfa]
plot(t, energy, 'LineWidth', 1.5); %[output:78cbdbfa]
grid on; %[output:78cbdbfa]
xlabel('Hour'); %[output:78cbdbfa]
ylabel('Energy (kWh)'); %[output:78cbdbfa]
title('Energy Usage Over Time'); %[output:78cbdbfa]

% (ii) Histogram
figure; %[output:3e5e5dfe]
histogram(energy); %[output:3e5e5dfe]
grid on; %[output:3e5e5dfe]
xlabel('Energy (kWh)'); %[output:3e5e5dfe]
ylabel('Frequency'); %[output:3e5e5dfe]
title('Energy Usage Distribution'); %[output:3e5e5dfe]

% (iii) Weekday vs Weekend comparison

days = ceil(t/24);
dayOfWeek = mod(days-1,7) + 1; % 1=Monday, 7=Sunday

weekday = energy(dayOfWeek <= 5);
weekend = energy(dayOfWeek >= 6);

figure;
boxplot([weekday; weekend], ... %[output:group:7e3c2a5a] %[output:95de08c6]
    [ones(size(weekday)); 2*ones(size(weekend))]); %[output:group:7e3c2a5a] %[output:95de08c6]
set(gca, 'XTickLabel', {'Weekday', 'Weekend'});
ylabel('Energy (kWh)');
title('Weekday vs Weekend Usage');

%% (iv) Simple dashboard figure

figure;

subplot(2,2,1);
plot(t, energy);
title('Time Series');

subplot(2,2,2);
histogram(energy);
title('Histogram');

subplot(2,2,3);
boxplot([weekday; weekend], ...
    [ones(size(weekday)); 2*ones(size(weekend))]);
title('Weekday vs Weekend');

subplot(2,2,4);
bar(weeklyTotals);
title('Weekly Totals');

%% Step 4: Interventions

disp("Peak usage (kWh):");
disp(maxUsage);

disp("Hour of peak usage:");
disp(peakIndex);

disp("Intervention Ideas:");
disp("1. Shift high-energy appliances to off-peak hours.");
disp("2. Reduce evening usage by limiting heavy devices.");

% Simple what-if: reduce peak by 20%
reducedPeak = maxUsage * 0.8;

disp("Reduced peak (20 percent cut):");
disp(reducedPeak);

